#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [RotationalStiffnessPerLength; 5] = [
        RotationalStiffnessPerLength::const_new(
            1234.5,
            RotationalStiffnessPerLengthUnit::NewtonMeterPerRadianPerMeter,
        ),
        RotationalStiffnessPerLength::const_new(
            1234.5,
            RotationalStiffnessPerLengthUnit::KilonewtonMeterPerRadianPerMeter,
        ),
        RotationalStiffnessPerLength::const_new(
            1234.5,
            RotationalStiffnessPerLengthUnit::MeganewtonMeterPerRadianPerMeter,
        ),
        RotationalStiffnessPerLength::const_new(
            1234.5,
            RotationalStiffnessPerLengthUnit::PoundForceFootPerDegreesPerFoot,
        ),
        RotationalStiffnessPerLength::const_new(
            1234.5,
            RotationalStiffnessPerLengthUnit::KilopoundForceFootPerDegreesPerFoot,
        ),
    ];
    for (q, &unit) in AT_COMPILE_TIME
        .iter()
        .zip(RotationalStiffnessPerLengthUnit::ALL)
    {
        assert_eq!(
            q.as_base().to_bits(),
            RotationalStiffnessPerLength::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in RotationalStiffnessPerLengthUnit::ALL {
            assert_eq!(
                RotationalStiffnessPerLength::const_new(v, unit)
                    .as_base()
                    .to_bits(),
                RotationalStiffnessPerLength::<f64>::new(v, unit)
                    .as_base()
                    .to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = RotationalStiffnessPerLength::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            RotationalStiffnessPerLength::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in RotationalStiffnessPerLengthUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        RotationalStiffnessPerLength::from_base(0.0)
            .auto_unit()
            .unit,
        RotationalStiffnessPerLengthUnit::NewtonMeterPerRadianPerMeter
    );
}

